import {fields,sampleData,validateCSV,filterRecords,calculate,trend,group,csv} from './analytics.js';
const $=s=>document.querySelector(s),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let records=sampleData(),imported=false,current=[],criteria;const colors=['#3e7c5b','#91ad77','#c3cf9f','#d9c89e','#94b4b0'];
try{const saved=localStorage.getItem('pagemetrics-data');if(saved){const result=validateCSV(saved);if(result.status==='SUCCESS'){records=result.accepted;imported=true;}}}catch{$('#message').innerHTML='<div class="notice">Saved data could not be loaded. Showing sample data.</div>';}
function options(){for(const key of ['subject','deweyClass','resourceId','format']){const select=$(`[name=${key}]`);select.innerHTML=`<option value="">All ${key==='resourceId'?'resources':key==='deweyClass'?'classes':key==='subject'?'subjects':'formats'}</option>`+[...new Set(records.map(r=>r[key]))].sort().map(v=>`<option value="${esc(v)}">${esc(key==='resourceId'?records.find(r=>r.resourceId===v).title:v)}</option>`).join('');}$('#dataset-label').textContent=imported?'Your imported dataset':'Exploring sample data';}
function bars(id,values){const sorted=Object.entries(values).sort((a,b)=>b[1]-a[1]);const max=Math.max(...sorted.map(x=>x[1]),1);$(id).innerHTML=sorted.map(([key,n],i)=>`<div class="bar-row"><div class="bar-title"><span>${esc(key)}</span><b>${n.toLocaleString()}</b></div><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%;background:${colors[i%colors.length]}"></div></div></div>`).join('');}
function render(){const k=calculate(current);$('#total').textContent=k.total.toLocaleString();$('#readers').textContent=k.readers.toLocaleString();$('#rate').textContent=k.rate===null?'N/A':k.rate.toFixed(1)+'%';$('#empty').hidden=!!k.total;$('#charts').hidden=!k.total;$('#range-label').textContent=`${criteria.start} — ${criteria.end} · ${k.total.toLocaleString()} records`;
 const values=trend(current,criteria.grouping),max=Math.max(...values.map(x=>x[1]),1);const w=Math.max(500,values.length*35),step=(w-50)/Math.max(values.length,1),points=values.map(([,n],i)=>`${40+i*step+step/2},${155-n/max*125}`);$('#trend').innerHTML=`<svg viewBox="0 0 ${w} 195" role="img" aria-label="Borrowing activity: ${esc(values.map(([l,n])=>l+': '+n).join(', '))}">${[0,.5,1].map(t=>`<line x1="35" x2="${w}" y1="${155-t*125}" y2="${155-t*125}" stroke="#e9eee6" stroke-dasharray="3 4"/><text x="0" y="${159-t*125}" font-size="9" fill="#9ba795">${Math.round(max*t)}</text>`).join('')}${values.length?`<polygon points="${40+step/2},155 ${points.join(' ')} ${40+(values.length-1)*step+step/2},155" fill="#eff5e9"/><polyline points="${points.join(' ')}" fill="none" stroke="#719268" stroke-width="2.5"/>`:''}${values.map(([l,n],i)=>`<circle cx="${40+i*step+step/2}" cy="${155-n/max*125}" r="3.5" fill="#fff" stroke="#719268"><title>${esc(l)}: ${n} checkouts</title></circle><text x="${40+i*step+step/2}" y="181" font-size="9" text-anchor="middle" fill="#8d9b87">${esc(criteria.grouping==='MONTHLY'?new Date(l+'-01T00:00:00Z').toLocaleDateString('en',{month:'short',timeZone:'UTC'}):l.slice(5))}</text>`).join('')}</svg>`;
 const formats=Object.entries(group(current,'format')).sort((a,b)=>b[1]-a[1]);let cursor=0;const stops=formats.map(([,n],i)=>{const start=cursor;cursor+=n/(k.total||1)*100;return `${colors[i%5]} ${start}% ${cursor}%`;});$('#format-chart').innerHTML=`<div class="format-wrap"><div class="donut" style="background:conic-gradient(${stops.join(',')||'#eee 0% 100%'})"><div>${formats.length}<small>formats</small></div></div><div class="format-legend">${formats.map(([name,n],i)=>`<div class="format-item"><span><i style="background:${colors[i%5]}"></i>${esc(name)}</span><b>${(n/(k.total||1)*100).toFixed(0)}%</b></div>`).join('')}</div></div>`;bars('#subjects',group(current,'subject'));bars('#segments',group(current,'userSegment'));renderTable();}
function renderTable(){const counts=group(current,'resourceId'),rows=Object.entries(counts).sort((a,b)=>$('#rank').value==='most'?b[1]-a[1]:a[1]-b[1]);$('#resource-rows').innerHTML=rows.map(([id,n])=>{const r=current.find(r=>r.resourceId===id);return `<tr><td>${esc(r.title)}</td><td>${esc(r.subject)}</td><td><span class="tag">${esc(r.format)}</span></td><td><b>${n}</b></td><td>${(n/current.length*100).toFixed(1)}%</td></tr>`;}).join('')||'<tr><td colspan="5">No matching resources</td></tr>';}
function apply(){try{const next=Object.fromEntries(new FormData($('#filters')));const result=filterRecords(records,next);criteria=next;current=result;$('#message').innerHTML='';render();}catch(e){$('#message').innerHTML=`<div class="notice">${esc(e.message)} Previous results are retained.</div>`;}}
$('#filters').onsubmit=e=>{e.preventDefault();apply();};$('#clear').onclick=()=>{$('#filters').reset();apply();};$('#rank').onchange=renderTable;
function page(name){$('#analytics-page').hidden=name==='imports';$('#imports-page').hidden=name!=='imports';$('#page-title').textContent=({overview:'Library overview',resources:'Resource insights',imports:'Import circulation data'})[name];$('#breadcrumb').textContent=({overview:'Overview',resources:'Resource insights',imports:'Import data'})[name];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===name));if(name==='resources')$('.resources').scrollIntoView({behavior:'smooth',block:'start'});else window.scrollTo(0,0);}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>page(b.dataset.page));$('#import-shortcut').onclick=()=>page('imports');
function download(content,name,type='text/csv'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#template').onclick=()=>download(csv(sampleData().slice(0,3)),'pagemetrics-template.csv');$('#schema').textContent=fields.join(', ');
$('#upload').onclick=async()=>{const file=$('#file').files[0],out=$('#import-result');try{if(!file||!file.name.toLowerCase().endsWith('.csv'))throw Error('Choose a CSV file first.');if(file.size>5*1024*1024)throw Error('Files must be smaller than 5 MB.');$('#upload').disabled=true;out.textContent='Validating file…';const result=validateCSV(await file.text());if(result.accepted.length){localStorage.setItem('pagemetrics-data',csv(result.accepted));records=result.accepted;imported=true;options();const dates=records.map(r=>r.checkoutDate).sort();$('[name=start]').value=dates[0];$('[name=end]').value=dates.at(-1);apply();}out.innerHTML=`<div class="notice ${result.accepted.length?'success':''}"><b>${result.status.replaceAll('_',' ')}</b><p>${result.accepted.length} imported · ${result.errors.length} rejected. ${result.accepted.length?'Current dataset replaced.':'Previous dataset retained.'}</p>${result.errors.slice(0,100).map(e=>`<div>Data row ${e.row}: ${esc(e.reason)}</div>`).join('')}${result.errors.length>100?'<p>Showing the first 100 validation errors.</p>':''}</div>`;}catch(e){out.innerHTML=`<div class="notice">${esc(e.message)} No data was changed.</div>`;}finally{$('#upload').disabled=false;}};
$('#restore').onclick=()=>{try{localStorage.removeItem('pagemetrics-data');records=sampleData();imported=false;options();$('#filters').reset();apply();$('#import-result').innerHTML='<div class="notice success">Sample data restored.</div>';}catch{$('#import-result').textContent='Storage is unavailable. Dataset unchanged.';}};
$('#export').onclick=()=>{const summary=Object.entries(group(current,'subject'));download('Subject,Checkouts\n'+summary.map(([s,n])=>'"'+s.replaceAll('"','""')+'",'+n).join('\n'),'pagemetrics-subject-summary.csv');};options();apply();
